        let webVideoUrl = "/InsWebApp/ui/videochat/webRTCVideoChatPage.xml";
        webVideoUrl += "?projectId=" + encodeURIComponent(projectId);
        webVideoUrl += "&userId=" + encodeURIComponent(currentUser.userId);
