// WebRTC 화상통화 시작
/**
 * WebRTC 화상통화 공식 시작
 * RTCPeerConnection 생성, WebSocket 연결, 방 참가 뤼 전체 화상통화 프로세스 실행
 * @async
 * @returns {Promise<void>} 화상통화 시작 완료 Promise
 * @throws {Error} PeerConnection 생성 또는 WebSocket 연결 실패 시 에러
 */
scwin.startWebRTCCall = async function() {
    try {

        scwin.showLoading("화상통화 연결 중...");

        // RTCPeerConnection 테스트


        const iceServers = [
            { urls: 'stun:stun.l.google.com:19302' },
            { urls: 'stun:stun1.l.google.com:19302' }
        ];

        const testPC = new RTCPeerConnection({ iceServers: iceServers });


        // 로컬 스트림을 PeerConnection에 추가 테스트
        if (localStream) {
            localStream.getTracks().forEach(track => {
                testPC.addTrack(track, localStream);
            });

        }

        // 본인 비디오 추가 (이미 2단계에서 완료됨)

        // WebSocket 연결 테스트

        const wsUrl = `wss://${location.hostname}:19443/InsWebApp/chat`;


        // 기존 WebSocket이 있으면 사용, 없으면 새로 생성
        if (!chatSocket || chatSocket.readyState !== WebSocket.OPEN) {
            scwin.initializeWebSocket();
        }

        // WebSocket 연결 대기
        setTimeout(function() {
            if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {


                // 화상통화 방 참가 알림
                const joinRoomMessage = {
                    type: 'join-room',
                    channelName: currentUser.channelName,
                    userId: currentUser.userId,
                    userName: currentUser.userName,
                    timestamp: Date.now()
                };
                chatSocket.send(JSON.stringify(joinRoomMessage));

            } else {

            }
        }, 2000);

        isJoined = true;
        dma_videoChat.set("isJoined", "true");

        scwin.hideLoading();



    } catch (error) {


        scwin.hideLoading();

    }
};

// WebSocket 메시지 처리
/**
 * WebSocket 메시지 처리 함수
 * 서버로부터 받은 시그널링 메시지를 타입별로 분류하여 처리
 * @param {Object} data - 파싱된 WebSocket 메시지 객체
 * @param {string} data.type - 메시지 타입 (join-room, offer, answer, ice-candidate 등)
 * @param {string} data.userId - 발신자 사용자 ID
 * @param {string} [data.userName] - 발신자 사용자명
 * @returns {void}
 */
scwin.handleWebSocketMessage = function(data) {


    switch(data.type) {
        case "join-room":
        case "user-joined":
            if (data.userId !== currentUser.userId) {
                scwin.handleUserJoined(data);
            }
            break;
        case "leave-room":
        case "user-left":
            scwin.handleUserLeft(data);
            break;
        case "OFFER":
        case "offer":
            scwin.handleOffer(data);
            break;
        case "ANSWER":
        case "answer":
            scwin.handleAnswer(data);
            break;
        case "ICE_CANDIDATE":
        case "ice-candidate":
            scwin.handleIceCandidate(data);
            break;
        case "existing-users":
            scwin.handleExistingUsers(data);
            break;
        case "history":
            // 채팅 기록 - 무시

            break;
        case "notification":
            // 알림 메시지 - 무시  

            break;
        case "error":
            // 서버 오류 메시지 처리

            break;
        default:

    }
};

